{
  "imports": [
    "from decimal import Decimal",
    "import pytest",
    "from ledger.fees import card_fee"
  ],
  "tests": [
    {
      "name": "test_card_fee_applies_minimum_when_percentage_below_minimum",
      "intent": "minimum fee is charged when percentage fee is below minimum",
      "code": "# intent: minimum fee is charged when percentage fee is below minimum\ndef test_card_fee_applies_minimum_when_percentage_below_minimum():\n    assert card_fee(Decimal(\"5.00\")) == Decimal(\"0.30\")\n"
    },
    {
      "name": "test_card_fee_uses_percentage_when_above_minimum",
      "intent": "percentage fee is charged when it exceeds minimum",
      "code": "# intent: percentage fee is charged when it exceeds minimum\ndef test_card_fee_uses_percentage_when_above_minimum():\n    assert card_fee(Decimal(\"100.00\")) == Decimal(\"2.90\")\n"
    },
    {
      "name": "test_card_fee_exact_minimum_boundary",
      "intent": "fee equals minimum when percentage equals minimum",
      "code": "# intent: fee equals minimum when percentage equals minimum\ndef test_card_fee_exact_minimum_boundary():\n    # amount such that 2.9% = 0.30: 0.30 / 0.029 = 10.344827...\n    # use amount = 10.3448275862069, fee = 0.30 after rounding\n    amount = Decimal(\"10.3448275862069\")\n    assert card_fee(amount) == Decimal(\"0.30\")\n"
    },
    {
      "name": "test_card_fee_just_below_minimum_boundary",
      "intent": "fee is minimum when percentage is just below minimum",
      "code": "# intent: fee is minimum when percentage is just below minimum\ndef test_card_fee_just_below_minimum_boundary():\n    # amount slightly less than the exact boundary\n    amount = Decimal(\"10.34\")\n    assert card_fee(amount) == Decimal(\"0.30\")\n"
    },
    {
      "name": "test_card_fee_just_above_minimum_boundary",
      "intent": "fee is percentage when percentage is just above minimum",
      "code": "# intent: fee is percentage when percentage is just above minimum\ndef test_card_fee_just_above_minimum_boundary():\n    # amount slightly more than the exact boundary\n    amount = Decimal(\"10.35\")\n    assert card_fee(amount) == Decimal(\"0.30\")\n"
    },
    {
      "name": "test_card_fee_zero_amount_charges_minimum",
      "intent": "zero amount still incurs minimum fee",
      "code": "# intent: zero amount still incurs minimum fee\ndef test_card_fee_zero_amount_charges_minimum():\n    assert card_fee(Decimal(\"0.00\")) == Decimal(\"0.30\")\n"
    }
  ]
}
